import json,numpy as np
from PIL import Image
m=json.load(open('/app/output/latest/meta.json'));cam=m['cameras']['robot0_eye_in_hand'];T=np.array(cam['cam2world_gl']);K=np.array(cam['intrinsic_cv']);d=np.load('/app/output/latest/depth_robot0_eye_in_hand.npy')[0];im=np.array(Image.open('/app/output/latest/last/robot0_eye_in_hand.jpg'))
mask=(im[:,:,2].astype(int)>im[:,:,0].astype(int)+25)&(im[:,:,2].astype(int)>im[:,:,1].astype(int)+10)&(im[:,:,2]>30)&(np.indices(im.shape[:2])[0]>150)
ys,xs=np.where(mask);print('count',len(xs),'bbox',(xs.min(),xs.max(),ys.min(),ys.max()))
# components 4-connected
seen=np.zeros(mask.shape,bool); comps=[]
for y,x in zip(ys,xs):
 if seen[y,x]:continue
 stack=[(y,x)];seen[y,x]=1; pts=[]
 while stack:
  yy,xx=stack.pop();pts.append((yy,xx))
  for ny,nx in [(yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)]:
   if 0<=ny<240 and 0<=nx<320 and mask[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;stack.append((ny,nx))
 if len(pts)>4:comps.append(pts)
for pts in sorted(comps,key=len,reverse=True)[:20]:
 a=np.array(pts); Y,X=a[:,0],a[:,1];Z=d[Y,X]; valid=Z>0; world=[]
 for y,x,z in zip(Y[valid],X[valid],Z[valid]): world.append(T[:3,:3]@np.array([(x-160)*z/K[0,0],-(y-120)*z/K[1,1],-z])+T[:3,3])
 w=np.array(world);print('comp',len(pts),'bbox',(X.min(),X.max(),Y.min(),Y.max()),'depth',np.percentile(Z[valid],[10,50,90]).round(3),'world med',np.median(w,axis=0).round(3))
print('eef',m['proprio']['now'][26:29])
